from django.db import migrations, models


def migrate_ticket_statuses(apps, schema_editor):
    """
    Preserve the old internal ticket status in creation_status
    before status starts storing the actual SEP status.
    """
    JoiningKitTicket = apps.get_model(
        "onboarding",
        "JoiningKitTicket",
    )

    old_statuses = ["pending", "creating", "created", "failed"]

    for old_status in old_statuses:
        JoiningKitTicket.objects.filter(
            status=old_status
        ).update(
            creation_status=old_status,
            status="",
        )


